package com.mediassistrover.backend.service.impl;
import com.mediassistrover.backend.dto.common.DeletionContracts.*;import com.mediassistrover.backend.exception.*;import lombok.RequiredArgsConstructor;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.nio.ByteBuffer;import java.util.*;import java.util.UUID;
@Service @RequiredArgsConstructor public class ShiftHardDeleteService {private final JdbcTemplate jdbc;
 @Transactional(readOnly=true) public DeletionImpactResponse impact(String table,String column,UUID id){byte[]k=key(id);exists(table,column,k,id);Map<String,Long>r=refs(table,k);List<String>b=r.entrySet().stream().filter(e->e.getValue()>0&&!((table.equals("Shift"))&&e.getKey().equals("Slot.shift_id"))).map(e->e.getKey()+" has "+e.getValue()+" reference(s)").toList();return new DeletionImpactResponse(id,table,b.isEmpty(),b,Map.copyOf(r));}
 @Transactional(propagation=Propagation.MANDATORY) public HardDeleteResponse delete(String table,String column,UUID id){byte[]k=key(id);if(jdbc.query("SELECT `"+column+"` FROM `"+table+"` WHERE `"+column+"`=? FOR UPDATE",(r,n)->r.getBytes(1),k).isEmpty())throw new ResourceNotFoundException(table+" not found: "+id);var i=impact(table,column,id);if(!i.canHardDelete())throw new ConflictException(String.join(", ",i.blockers()));var d=new LinkedHashMap<String,Long>();if(table.equals("Shift"))d.put("Slot",(long)jdbc.update("DELETE FROM Slot WHERE shift_id=?",k));d.put(table,(long)jdbc.update("DELETE FROM `"+table+"` WHERE `"+column+"`=?",k));return new HardDeleteResponse(id,table,Map.copyOf(d));}
 private Map<String,Long> refs(String table,byte[]k){var o=new LinkedHashMap<String,Long>();var rs=jdbc.query("SELECT TABLE_NAME,COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE REFERENCED_TABLE_SCHEMA=DATABASE() AND REFERENCED_TABLE_NAME=? ORDER BY TABLE_NAME,COLUMN_NAME",(r,n)->List.of(r.getString(1),r.getString(2)),table);for(var x:rs){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM `"+x.get(0)+"` WHERE `"+x.get(1)+"`=?",Long.class,k);o.put(x.get(0)+"."+x.get(1),n==null?0:n);}return o;}private void exists(String t,String c,byte[]k,UUID id){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM `"+t+"` WHERE `"+c+"`=?",Long.class,k);if(n==null||n==0)throw new ResourceNotFoundException(t+" not found: "+id);}private static byte[]key(UUID id){return ByteBuffer.allocate(16).putLong(id.getMostSignificantBits()).putLong(id.getLeastSignificantBits()).array();}}
